let sourceTitle = "Moon Book";
let cache = null;
function readTitle(now) {
  if (cache !== null && now < cache.expiresAt) {
    return `hit: ${cache.value}`;
  }
  cache = { value: sourceTitle, expiresAt: now + 10 };
  return `miss: ${cache.value}`;
}
console.log(readTitle(0));
console.log(readTitle(5));
sourceTitle = "Moon and Stars";
console.log(readTitle(6));
console.log(readTitle(10));
